EMBEDDED_ACADEMY_LOGO_B64 = ""


def load_academy_logo_bytes(base_dir: Path) -> bytes:
    for candidate in ("Logo học viện.jpg", "logo_hoc_vien.png", "logo.png", "logo.jpg"):
        p = base_dir / candidate
        if p.exists():
            try:
                from PIL import Image, ImageDraw

                im = Image.open(p).convert("RGBA")
                sz = (128, 128)
                im = im.resize(sz, Image.Resampling.LANCZOS)
                mask = Image.new("L", (sz[0] * 2, sz[1] * 2), 0)
                draw = ImageDraw.Draw(mask)
                draw.ellipse((4, 4, sz[0] * 2 - 5, sz[1] * 2 - 5), fill=255)
                im.putalpha(mask.resize(sz, Image.Resampling.LANCZOS))
                out = io.BytesIO()
                im.save(out, format="PNG", optimize=True)
                return out.getvalue()
            except Exception:
                break
    return base64.b64decode(EMBEDDED_ACADEMY_LOGO_B64)


class LegalSearchApplication:
    """Lõi điều phối nghiệp vụ trung tâm cho cả Giao diện Web và RESTful API."""

    def __init__(self, base_dir: Path | None = None):
        self.base_dir = base_dir or get_app_base_dir()
        self.corpus_path = self.base_dir / "corpus.jsonl"
        self.queries_path = self.base_dir / "queries.jsonl"
        self.eval_dir = self.base_dir / "evaluation"
        self.logs_path = self.base_dir / "logs" / "query_rewrite_audit.jsonl"
        self._lock = threading.Lock()
        self.logo_bytes = load_academy_logo_bytes(self.base_dir)

        print(f"[*] Đang khởi tạo HybridRetriever từ: {self.corpus_path} ...")
        self.retriever = HybridRetriever(self.corpus_path)
        hw = self.retriever.hardware_info
        print(
            f"[+] Phần cứng tính toán: {hw['backend']} - {hw['device_name']} (Batch size: {hw['batch_size']})"
        )
        print(
            f"[+] Hoàn tất đồng bộ chỉ mục: {self.retriever.last_index_stats['total_documents']} điều khoản "
            f"(Tái sử dụng {self.retriever.last_index_stats['reused_embeddings']} vector từ embeddings.npy, "
            f"thời gian đồng bộ: {self.retriever.last_index_stats['sync_time_ms']} ms)."
        )

    def get_system_status(self) -> dict[str, Any]:
        ollama_info = check_ollama_status()
        ocr_info = get_ocr_capabilities_status()
        active_docs = sum(
            1 for r in self.retriever.rows if r.get("status", "active") == "active"
        )
        replaced_docs = len(self.retriever.rows) - active_docs

        doc_type_counts: dict[str, int] = {}
        for r in self.retriever.rows:
            if r.get("status", "active") == "active":
                dt_label = str(r.get("doc_type", "Văn bản pháp quy khác"))
                doc_type_counts[dt_label] = doc_type_counts.get(dt_label, 0) + 1

        return {
            "total_chunks": len(self.retriever.rows),
            "active_chunks": active_docs,
            "replaced_chunks": replaced_docs,
            "doc_type_counts": doc_type_counts,
            "suggested_queries": self.retriever.generate_suggested_queries(),
            "hardware": self.retriever.hardware_info,
            "ocr_capabilities": ocr_info,
            "index_stats": self.retriever.last_index_stats,
            "embeddings_file_exists": self.retriever.embeddings_path.exists(),
            "ollama": ollama_info,
        }

    def handle_search(self, payload: dict[str, Any]) -> dict[str, Any]:
        question = str(payload.get("query", "")).strip()
        if not question:
            raise ValueError("Vui lòng nhập nội dung câu hỏi tra cứu.")

        history = str(payload.get("history", "")).strip()
        use_rewrite = bool(payload.get("use_rewrite", True))
        top_k = max(1, min(20, int(payload.get("top_k", 5))))
        rrf_k = max(1, int(payload.get("rrf_k", 60)))
        bm25_weight = max(0.0, float(payload.get("bm25_weight", 1.0)))
        dense_weight = max(0.0, float(payload.get("dense_weight", 1.0)))
        include_replaced = bool(payload.get("include_replaced", False))
        doc_type_filter = str(payload.get("doc_type_filter", "all")).strip()

        # Khi bật Chuẩn hóa câu hỏi: hoạt động ngay cả ở Lượt 1 (khi history trống)
        # để chuẩn hóa khẩu ngữ, từ viết tắt và khớp số hiệu văn bản mới trong kho!
        if use_rewrite:
            trace = rewrite_query_with_trace(
                history,
                question,
                use_ollama_default=True,
                corpus_doc_numbers=self.retriever.get_active_doc_numbers(),
                corpus_catalog_summary=self.retriever.build_corpus_catalog_hint(),
            )
            effective_query = str(trace["rewritten"])
        else:
            trace = {
                "original": question,
                "rewritten": question,
                "used_rewrite": False,
                "status": "disabled",
                "notes": [],
                "latency_ms": 0.0,
                "model": None,
                "error": None,
            }
            effective_query = question

        search_res = self.retriever.search(
            effective_query,
            top_k=top_k,
            rrf_k=rrf_k,
            bm25_weight=bm25_weight,
            dense_weight=dense_weight,
            include_replaced=include_replaced,
            doc_type_filter=doc_type_filter,
        )
        return {
            "query_trace": trace,
            "effective_query": effective_query,
            "results": search_res,
        }

    def list_documents(
        self,
        *,
        keyword: str = "",
        status_filter: str = "all",
        doc_type_filter: str = "all",
        limit: int = 500,
    ) -> dict[str, Any]:
        kw = keyword.strip().lower()
        dt_filter = doc_type_filter.strip().lower()
        filtered: list[dict[str, Any]] = []

        for row in reversed(self.retriever.rows):
            st = row.get("status", "active")
            if status_filter != "all" and st != status_filter:
                continue
            r_type = str(
                row.get("doc_type")
                or classify_legal_doc_type(
                    str(row.get("doc_number", "")), row["title"], row["text"]
                )
            )
            if dt_filter not in ("all", "") and dt_filter not in r_type.lower():
                continue
            if kw:
                haystack = (
                    f"{row.get('id', '')} {row.get('doc_number', '')} "
                    f"{r_type} {row.get('title', '')} {row.get('text', '')}"
                ).lower()
                if kw not in haystack:
                    continue
            filtered.append(
                {
                    "id": row["id"],
                    "doc_number": row.get("doc_number", "CHƯA_RÕ_SỐ_HIỆU"),
                    "doc_type": r_type,
                    "title": row["title"],
                    "text_preview": row["text"][:280]
                    + ("..." if len(row["text"]) > 280 else ""),
                    "source": row.get("source", ""),
                    "status": st,
                    "replaced_by": row.get("replaced_by"),
                    "added_at": row.get("added_at", "Dữ liệu gốc"),
                }
            )
            if len(filtered) >= limit:
                break

        return {
            "total_matched": len(filtered),
            "total_in_corpus": len(self.retriever.rows),
            "items": filtered,
        }

    def preview_document_ingestion(self, payload: dict[str, Any]) -> dict[str, Any]:
        filename = str(payload.get("filename", "van_ban_moi.txt")).strip()
        raw_text_input = str(payload.get("raw_text", "")).strip()
        file_b64 = str(payload.get("file_base64", "")).strip()
        force_ocr = bool(payload.get("force_ocr", False))
        use_llm_check = bool(payload.get("use_llm_check", True))

        if file_b64:
            is_valid_fmt, _ext, fmt_msg = validate_uploaded_file_format(filename, None)
            if not is_valid_fmt:
                raise ValueError(fmt_msg)
            if "," in file_b64:
                file_b64 = file_b64.split(",", 1)[1]
            file_bytes = base64.b64decode(file_b64)
            is_valid_bytes, _ext, fmt_bytes_msg = validate_uploaded_file_format(filename, file_bytes)
            if not is_valid_bytes:
                raise ValueError(fmt_bytes_msg)
            extraction = extract_text_from_uploaded_file(
                filename, file_bytes, force_ocr=force_ocr
            )
            extracted_text = extraction["text"]
        elif raw_text_input:
            extracted_text = normalize_vietnamese_text(raw_text_input)
            extraction = {
                "text": extracted_text,
                "extraction_method": "Nhập văn bản trực tiếp trên giao diện",
                "pages": 1,
                "ocr_used": False,
                "hardware_used": "CPU",
            }
        else:
            raise ValueError(
                "Vui lòng chọn tệp văn bản (.doc, .docx, .pdf, .txt) hoặc dán nội dung văn bản."
            )

        validation = validate_legal_document(
            extracted_text,
            filename=filename,
            use_llm_check=use_llm_check,
        )

        custom_doc_num = (
            str(payload.get("doc_number", "")).strip()
            or validation["detected_doc_number"]
        )
        custom_title = (
            str(payload.get("doc_title", "")).strip()
            or validation["detected_title"]
        )
        custom_doc_type = (
            str(payload.get("doc_type", "")).strip()
            or validation["detected_doc_type"]
        )
        custom_source = (
            str(payload.get("source", "")).strip()
            or f"Tải lên từ {filename} (Kho văn bản nội bộ)"
        )

        chunks = chunk_legal_document(
            extracted_text,
            doc_number=custom_doc_num,
            doc_title=custom_title,
            doc_type=custom_doc_type,
            source=custom_source,
        )

        duplicate_check = self.retriever.check_duplicate_document(
            chunks,
            doc_number=custom_doc_num,
            doc_title=custom_title,
        )

        return {
            "extraction": {
                "filename": filename,
                "method": extraction["extraction_method"],
                "pages": extraction["pages"],
                "ocr_used": extraction["ocr_used"],
                "hardware_used": extraction.get("hardware_used", ""),
                "char_count": len(extracted_text),
                "raw_text": extracted_text,
                "ocr_capabilities": get_ocr_capabilities_status(),
            },
            "validation": validation,
            "duplicate_check": duplicate_check,
            "proposed_metadata": {
                "doc_number": custom_doc_num,
                "doc_type": custom_doc_type,
                "doc_title": custom_title,
                "source": custom_source,
            },
            "chunks_count": len(chunks),
            "chunks": chunks,
        }

    def commit_document_ingestion(self, payload: dict[str, Any]) -> dict[str, Any]:
        chunks = payload.get("chunks")
        if not isinstance(chunks, list) or not chunks:
            raise ValueError("Không có điều khoản nào để nạp vào kho dữ liệu.")

        replace_doc_number = str(payload.get("replace_doc_number", "")).strip() or None
        conflict_mode = str(payload.get("conflict_mode", "auto")).strip()
        override_doc_type = str(payload.get("doc_type", "")).strip()
        override_doc_num = str(payload.get("doc_number", "")).strip()
        override_doc_title = str(payload.get("doc_title", "")).strip()

        for ch in chunks:
            if override_doc_type:
                ch["doc_type"] = override_doc_type
            if override_doc_num:
                old_num = ch.get("doc_number", "")
                ch["doc_number"] = override_doc_num
                if old_num and old_num in ch.get("title", ""):
                    ch["title"] = ch["title"].replace(f"[{old_num}]", f"[{override_doc_num}]")
            if override_doc_title and " - Điều" in ch.get("title", ""):
                prefix_part, art_part = ch["title"].split(" - Điều", 1)
                d_num = ch.get("doc_number", "VB")
                ch["title"] = f"[{d_num}] {override_doc_title} - Điều{art_part}"

        replace_ids = payload.get("replace_ids")
        if isinstance(replace_ids, str) and replace_ids.strip():
            replace_ids_list = [
                x.strip() for x in replace_ids.split(",") if x.strip()
            ]
        elif isinstance(replace_ids, list):
            replace_ids_list = [
                str(x).strip() for x in replace_ids if str(x).strip()
            ]
        else:
            replace_ids_list = None

        with self._lock:
            stats = self.retriever.add_or_replace_documents(
                chunks,
                replace_doc_number=replace_doc_number,
                replace_ids=replace_ids_list,
                conflict_mode=conflict_mode,
            )
        return stats

    def delete_document_by_number(self, payload: dict[str, Any]) -> dict[str, Any]:
        doc_number = str(payload.get("doc_number", "")).strip()
        with self._lock:
            return self.retriever.delete_documents_by_doc_number(doc_number)

    def update_document_status(self, payload: dict[str, Any]) -> dict[str, Any]:
        chunk_id = str(payload.get("chunk_id", "")).strip() or None
        doc_number = str(payload.get("doc_number", "")).strip() or None
        scope = str(payload.get("scope", "single")).strip()
        new_status = str(payload.get("new_status", "replaced")).strip()
        replaced_by = str(payload.get("replaced_by", "")).strip()
        with self._lock:
            return self.retriever.update_documents_status(
                chunk_id=chunk_id,
                doc_number=doc_number,
                scope=scope,
                new_status=new_status,
                replaced_by=replaced_by,
            )

    def get_benchmark_and_logs(self, run_fresh: bool = False) -> dict[str, Any]:
        metrics_file = self.eval_dir / "metrics.json"
        if run_fresh or not metrics_file.exists():
            with self._lock:
                report = benchmark(
                    self.retriever,
                    self.queries_path,
                    self.eval_dir,
                    warmup_passes=1,
                    measured_passes=3 if run_fresh else 1,
                )
        else:
            report = json.loads(metrics_file.read_text(encoding="utf-8"))

        audit_logs: list[dict[str, Any]] = []
        if self.logs_path.exists():
            lines = self.logs_path.read_text(encoding="utf-8").splitlines()
            for ln in reversed(lines[-30:]):
                if ln.strip():
                    try:
                        audit_logs.append(json.loads(ln))
                    except Exception:
                        pass

        return {
            "benchmark": report,
            "audit_logs": audit_logs,
        }


